var counts = new Dictionary<int, int>();
s = s.Normalize();                                   // «é» — в одной форме
for (int i = 0; i < s.Length; i++) {
    int cp = char.ConvertToUtf32(s, i);              // суррогатная пара → одна точка
    if (char.IsSurrogatePair(s, i)) i++;
    counts[cp] = counts.GetValueOrDefault(cp) + 1;   // для нового ключа — 0 + 1
}

